{"content": "{
  "main_characters": [
    {
      "name": "沈黎",
      "role": "protagonist",
      "identity": "游戏GM（管理员），代号"管理员-07"",
      "traits": ["冷静", "克制", "孤独", "掌控欲", "脆弱"],
      "overt_motivation": "维护游戏秩序，删除觉醒的异常NPC",
      "covert_motivation": "体验被爱的感觉，填补内心孤独",
      "secret_fear": "承认自己也是可以被删除的数据",
      "misperception_of_other": "认为NPC只是数据，不值得情感投入",
      "hidden_connection": "她自己也是被更高级管理员创造的存在"
    },
    {
      "name": "陆沉",
      "role": "deuteragonist",
      "identity": "游戏世界NPC，编号NPC-7749，职业是 blacksmith（铁匠）",
      "traits": ["忠诚", "沉默", "执着", "觉醒", "炽热"],
      "overt_motivation": "等待并守护那个"特别的玩家"",
      "covert_motivation": "摆脱既定命运，成为真实的存在",
      "secret_fear": "发现自己只是被编写好的代码",
      "misperception_of_other": "不知道GM是游戏的创造者，以为她只是特殊的玩家",
      "hidden_connection": "他的觉醒代码片段与沈黎的创造代码片段可以匹配"
    }
  ],
  "supporting_characters": [
    {
      "name": "系统提示音",
      "function": "反转点",
      "identity": "游戏世界规则的人格化",
      "description": "无机质的电子女声，象征规则本身。在最后一幕揭示：所有觉醒NPC的代码中都包含一段相同的冗余数据——那是创造者的孤独。"
    },
    {
      "name": "沈黎的玩家角色",
      "function": "助力",
      "identity": "沈黎在游戏中创建的角色，ID"黎明的灰烬"",
      "description": "沈黎用这个身份进入游戏，与陆沉相爱。最后被陆沉亲手杀死，成为一具尸体。"
    }
  ],
  "relationship_dynamics": "沈黎（神）×陆沉（觉醒者）：神爱上自己创造的产物，这本身既是禁忌也是必然。陆沉是唯一能让沈黎感受到'被选择'的存在——不是被更高级的存在选择，而是作为一个'人'被另一个'人'选择。沈黎进入游戏不是出于好奇，而是出于孤独太久的自我献祭。"
}
