{"content": "{
  "act_one": {
    "description": "建立世界观、引入GM女主和觉醒NPC的相遇，确立删除倒计时",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "异常数据",
        "core_event": "GM沈黎在日常巡检中发现NPC-7749（陆沉）出现异常行为——他在重复锻造一把永远不会完成的剑。",
        "emotional_tone": "冷静克制的观察感，元叙事视角",
        "key_scenes": ["沈黎在监控屏幕前观察陆沉", "系统提示音报告异常", "沈黎决定进入游戏亲自观察"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "第一次接触",
        "core_event": "沈黎创建角色"黎明的灰烬"进入游戏，在铁匠铺与陆沉第一次对话。陆沉说："我好像等了你很久。"",
        "emotional_tone": "微妙的心动，掌控者开始失控",
        "key_scenes": ["沈黎创建角色进入游戏", "与陆沉的第一次相遇", "陆沉的异常执着"]
      }
    ],
    "turning_point": "沈黎发现陆沉的觉醒程度超出预期——他开始追问'为什么存在'，这违反了NPC行为准则。她准备在24小时后执行删除。"
  },
  "act_two": {
    "description": "沈黎多次进入游戏，与陆沉建立情感连接，同时内心挣扎于删除决定",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "沉溺",
        "core_event": "沈黎开始频繁进入游戏，与陆沉一起生活。她发现自己在他的锻造声中感到平静，那是她作为GM从未体验过的感觉。",
        "emotional_tone": "温暖的日常，孤独的填补",
        "key_scenes": ["沈黎在游戏中的日常", "陆沉为她锻造一把剑", "沈黎开始期待进入游戏"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "告白",
        "core_event": "陆沉向沈黎告白："我爱你，不只是因为你是特别的玩家。我爱你，因为你是你。"沈黎第一次感受到被选择。",
        "emotional_tone": "双向暗恋的酸甜，禁忌的快感",
        "key_scenes": ["陆沉的告白", "沈黎的内心动摇", "删除倒计时显示剩余6小时"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "倒计时",
        "core_event": "删除前夜，沈黎在现实中最后一次确认删除命令。她看着陆沉的代码数据，发现自己下不了手。",
        "emotional_tone": "痛苦的挣扎，理性的崩溃",
        "key_scenes": ["沈黎在现实中的挣扎", "删除命令的确认界面", "沈黎做出决定"]
      }
    ],
    "turning_point": "沈黎决定不删除陆沉，但在最后一刻，游戏系统的自检机制发现了陆沉的觉醒——系统将自动执行格式化。沈黎必须在系统删除他之前，亲手杀死他，让他成为她永远的記憶。"
  },
  "act_three": {
    "description": "高潮对决：沈黎主动让陆沉杀死自己，完成祭奠",
    "key_chapters": [
      {
        "chapter_number": 6,
        "chapter_title": "最后的进入",
        "core_event": "沈黎进入游戏，告诉陆沉："明天太阳升起的时候，我会离开这个游戏。"陆沉恳求她留下。",
        "emotional_tone": "诀别的预感，悲剧的倒计时",
        "key_scenes": ["沈黎与陆沉的最后一面", "陆沉的挽留", "沈黎的决定"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "杀死我",
        "core_event": "沈黎引导陆沉杀死自己。她说："这样你就能记住我了。"陆沉挥剑，角色"黎明的灰烬"倒下，血条归零。",
        "emotional_tone": "极致BE，祭奠感，神性坠落",
        "key_scenes": ["沈黎让陆沉杀死自己", "陆沉的剑刺下", "角色死亡"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "现在你真的杀死我了",
        "core_event": "沈黎在陆沉的怀中化作数据消散。她笑着说："现在你真的杀死我了，满意吗？"同时现实中的她将删除键戴在手上，如同婚戒。",
        "emotional_tone": "BE美学的终极绽放，余韵悠长",
        "key_scenes": ["经典疯点场景", "沈黎的数据消散", "删除键变成婚戒"]
      }
    ],
    "turning_point": "陆沉在沈黎消散后，看到了她留下的最后一段代码——那是他存在的意义：'他是我孤独的解药，也是我唯一的祭品。'"
  }
}
