  "act_one": {
    "description": "建立世界观、引入GM女主和觉醒NPC的相遇，确立删除倒计时",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "异常数据",
        "core_event": "GM沈黎在日常巡检中发现NPC-7749（陆沉）出现异常行为——他在重复锻造一把永远不会完成的剑。",
        "emotional_tone": "冷静克制的观察感，元叙事视角",
        "key_scenes": ["沈黎在监控屏幕前观察陆沉", "系统提示音报告异常", "沈黎决定进入游戏亲自观察"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "第一次接触",
        "core_event": "沈黎创建角色"黎明的灰烬"进入游戏，在铁匠铺与陆沉第一次对话。陆沉说："我好像等了你很久。"",
        "emotional_tone": "微妙的心动，掌控者开始失控",
        "key_scenes": ["沈黎创建角色进入游戏", "与陆沉的第一次相遇", "陆沉的异常执着"]
      }
    ],
    "turning_point": "沈黎发现陆沉的觉醒程度超出预期——他开始追问'为什么存在'，这违反了NPC行为准则。她准备在24小时后执行删除。"
  },
  "act_two": {
    "description": "沈黎多次进入游戏，与陆沉建立情感连接，同时内心挣扎于删除决定",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "沉溺",
        "core_event": "沈黎开始频繁进入游戏，与陆沉一起生活。她发现自己在他的锻造声中感到平静，那是她作为GM从未体验过的感觉。",
        "emotional_tone": "温暖的日常，孤独的填补",
        "key_scenes": ["沈黎在游戏中的日常", "陆沉为她锻造一把剑", "沈黎开始期待进入游戏"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "告白",
        "core_event": "陆沉向沈黎告白："我爱你，不只是因为你是特别的玩家。我爱你，因为你是你。"沈黎第一次感受到被选择。",
        "emotional_tone": "双向暗恋的酸甜，禁忌的快感",
        "key_scenes": ["陆沉的告白", "沈黎的内心动摇", "删除倒计时显示剩余6小时"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "倒计时",
        "core_event": "删除前夜，沈黎在现实中最后一次确认删除命令。她看着陆沉的代码数据，发现自己下不了手。",
        "emotional_tone": "痛苦的挣扎，理性的崩溃",
        "key_scenes": ["沈黎在现实中的挣扎", "删除命令的确认界面", "沈黎做出决定"]
      }
